            self.device.pop_error_scope(),
            self.device.pop_error_scope(),
        ]
    }
}

impl Drop for WgpuErrorScope {
    fn drop(&mut self) {
        if self.open {
            drop(self.device.pop_error_scope());
            drop(self.device.pop_error_scope());
            drop(self.device.pop_error_scope());
        }
    }
}
